function animate(env,el,p){
    var t=el.text, L=t.length, n=Math.round(L*env.time), out="";
    for(var i=0;i<L;i++){ var c=t.charAt(i);
        if( i<n || c==" " ){ out+=c; }
        else { var r=(AM.simplexNoise(i*4.0+env.absTime*10.0, p.seed)+1)/2; out+=t.charAt(Math.floor(r*L)%L); } }
    el.text=out; return el;
}
